-- Seed all US universities as campuses
-- Run with: sudo -u postgres psql -d campuscuts -f seed_campuses.sql

-- First, delete invalid entries
DELETE FROM campuses WHERE name IN ('GMAIL', 'ICLOUD');

-- Insert all universities (ON CONFLICT DO NOTHING to avoid duplicates)
ON CONFLICT (slug) DO NOTHING;

-- Show count of campuses
SELECT COUNT(*) as total_campuses FROM campuses;

